export const FRASE = Object.fromEntries(FRASES.map((f) => [f.id, f]));
export const SERIE = Object.fromEntries(SERIES.map((s) => [s.id, s]));
export const VIDEOS = FRASES.filter((f) => f.v);
// La música que le toca a una frase: la suya si la trae, o la de su serie
export const musicaDe = (f) => f?.m || SERIE[f?.s]?.m || 'piano';
